public with sharing class ContactTriggerHandler {

    public static void handle(List<Contact> newList) {
        if (newList == null || newList.isEmpty()) {
            return;
        }

        if (Trigger.isBefore) {
            handleBefore(newList);
        } else if (Trigger.isAfter && Trigger.isInsert) {
            handleAfterInsert(newList);
        }
    }

    private static void handleBefore(List<Contact> newList) {
        // Collect distinct account Ids
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newList) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // Query 1
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : newList) {
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (Trigger.isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    private static void handleAfterInsert(List<Contact> newList) {
        // Collect distinct account Ids for contacts with a phone
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newList) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // Query 2
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        // First contact (in trigger order) with a phone wins for its account
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : newList) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a != null && String.isBlank(a.Phone) && !accountsToUpdate.containsKey(c.AccountId)) {
                Account toUpdate = new Account(Id = c.AccountId, Phone = c.Phone);
                accountsToUpdate.put(c.AccountId, toUpdate);
            }
        }

        // Single DML statement
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
```

Notes on the refactor:

- **Bulk-safe**: both SOQL queries use a `Set<Id>` collected from the whole batch, giving at most 2 queries and 1 `update` DML for up to 200 contacts.
- **Trigger contains no logic**: it only delegates to `ContactTriggerHandler`.
- **Behaviour preserved**: the blank-phone check reads the account's current phone from the fresh query, and the "first contact in trigger order wins" rule is enforced by only inserting the first matching contact's phone into `accountsToUpdate` (a map keyed by AccountId, also preventing duplicates).

