public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final Integer MAX_ATTEMPTS = 2;

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String base = normaliseCode(baseCurrency);
        if (base == null) {
            throw new ExchangeRateException('Invalid base currency: "' + baseCurrency + '"');
        }

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies set is null or empty.');
        }

        Set<String> quotes = new Set<String>();
        for (String raw : quoteCurrencies) {
            String code = normaliseCode(raw);
            if (code == null) {
                throw new ExchangeRateException('Invalid quote currency: "' + raw + '"');
            }
            quotes.add(code);
        }

        String symbols = String.join(new List<String>(quotes), ',');

        Integer status;
        String body;
        Integer attempt = 0;
        do {
            attempt++;
            HttpResponse res = makeRequest(base, symbols);
            status = res.getStatusCode();
            body = res.getBody();
        } while (status == 503 && attempt < MAX_ATTEMPTS);

        if (status != 200) {
            throw new ExchangeRateException(
                'Exchange rate callout failed with status ' + status + ': ' + body
            );
        }

        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage());
        }

        Object ratesObj = parsed != null ? parsed.get('rates') : null;
        if (!(ratesObj instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response is missing the "rates" object.');
        }
        Map<String, Object> rates = (Map<String, Object>) ratesObj;

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : quotes) {
            Object rateObj = rates.get(code);
            if (rateObj instanceof Decimal) {
                result.put(code, (Decimal) rateObj);
            } else {
                throw new ExchangeRateException('No rate returned for currency ' + code + '.');
            }
        }
        return result;
    }

    private static HttpResponse makeRequest(String base, String symbols) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:FB_Exchange_Rates/v1/latest?base=' + EncodingUtil.urlEncode(base, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbols, 'UTF-8'));
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        return new Http().send(req);
    }

    private static String normaliseCode(String raw) {
        if (raw == null) {
            return null;
        }
        String code = raw.trim().toUpperCase();
        return Pattern.matches('^[A-Z]{3}$', code) ? code : null;
    }
}
