@IsTest
private class AddressVerificationServiceTest {

    private class AddressCalloutMock implements HttpCalloutMock {
        private Integer statusCode;
        private String body;
        private String lastBody;
        private HttpRequest lastRequest;

        AddressCalloutMock(Integer statusCode, String body) {
            this.statusCode = statusCode;
            this.body = body;
        }

        public HttpResponse respond(HttpRequest req) {
            this.lastRequest = req;
            this.lastBody = req.getBody();
            HttpResponse res = new HttpResponse();
            res.setStatusCode(this.statusCode);
            if (this.body != null) {
                res.setBody(this.body);
            }
            res.setHeader('Content-Type', 'application/json');
            return res;
        }
    }

    private static Account makeAccount(String street, String city, String postal, String country) {
        Account a = new Account();
        a.Name = 'Test Account';
        a.BillingStreet = street;
        a.BillingCity = city;
        a.BillingPostalCode = postal;
        a.BillingCountry = country;
        return a;
    }

    @IsTest
