        AddressCalloutMock mock = new AddressCalloutMock(200, '{"status":"VERIFIED"}');
        Test.setMock(HttpCalloutMock.class, mock);

        Account a = makeAccount(null, 'Denver', '80202', 'USA');
        AddressVerificationService.Result r = AddressVerificationService.verify(a);

        System.assertEquals('SKIPPED', r.status, 'Blank street should be skipped');
        System.assertEquals(false, r.changed, 'Nothing changed when skipped');
        System.assertEquals('Denver', a.BillingCity, 'Account untouched when skipped');

        // Also with whitespace-only street
        Account a2 = makeAccount('   ', 'Denver', '80202', 'USA');
        AddressVerificationService.Result r2 = AddressVerificationService.verify(a2);
        System.assertEquals('SKIPPED', r2.status, 'Whitespace street should be skipped');

        // No callout may have been made: assert request was never recorded.
        System.assertEquals(null, mock.lastRequest, 'No HTTP request should be sent for blank street');
    }

    @IsTest
    static void testRequestContract() {
        AddressCalloutMock mock = new AddressCalloutMock(200,
            '{"status":"VERIFIED","address":null}');
        Test.setMock(HttpCalloutMock.class, mock);

        Account a = makeAccount('1 Main St', 'Denver', '80202', 'USA');
        AddressVerificationService.verify(a);

        System.assertEquals('POST', mock.lastRequest.getMethod(), 'Method must be POST');
        System.assertEquals('callout:FB_Address_API/v2/verify', mock.lastRequest.getEndpoint(),
            'Endpoint must match contract');
        System.assertEquals('application/json', mock.lastRequest.getHeader('Content-Type'),
            'Content-Type header must be application/json');

        Map<String, Object> sent = (Map<String, Object>) JSON.deserializeUntyped(mock.lastBody);
        System.assertEquals('1 Main St', (String) sent.get('street'), 'street in request body');
        System.assertEquals('Denver', (String) sent.get('city'), 'city in request body');
        System.assertEquals('80202', (String) sent.get('postalCode'), 'postalCode in request body');
        System.assertEquals('USA', (String) sent.get('country'), 'country in request body');
        // exactly four keys
        System.assertEquals(4, sent.keySet().size(), 'Request body must have exactly the four contract keys');
    }

