        } catch (ShippingCostCalculator.ShippingException e) {
            threw = true;
        }
        System.assert(threw, 'Expected ShippingException for weight=' + weightKg +
            ', zone=' + zone + ', express=' + express + ', orderValue=' + orderValue);
    }

    // ---------- weight validation ----------

    @isTest
    static void testWeightValidation() {
        assertThrows(0, 'DOMESTIC', false, null);
        assertThrows(-0.01, 'DOMESTIC', false, null);
        assertThrows(-5, 'EU', true, 50);
        assertThrows(null, 'DOMESTIC', false, null);
    }

    // ---------- weight tiers (boundaries) ----------

    @isTest
    static void testWeightTierBoundaries() {
        // up to and including 1 kg: 5.00
        assertQuote(5.00, 0.01, 'DOMESTIC', false, null);
        assertQuote(5.00, 1, 'DOMESTIC', false, null);
        // above 1 up to 5 kg: 9.50
        assertQuote(9.50, 1.01, 'DOMESTIC', false, null);
        assertQuote(9.50, 5, 'DOMESTIC', false, null);
        // above 5 up to 20 kg: 18.00
        assertQuote(18.00, 5.01, 'DOMESTIC', false, null);
        assertQuote(18.00, 20, 'DOMESTIC', false, null);
        // above 20: 18.00 + 0.75 per started kilogram above 20
        assertQuote(18.75, 20.01, 'DOMESTIC', false, null);
        assertQuote(18.75, 21, 'DOMESTIC', false, null);
        assertQuote(19.50, 22, 'DOMESTIC', false, null);
        assertQuote(21.00, 24.99, 'DOMESTIC', false, null); // 5 started kg above 20
    }

    // ---------- zones ----------

    @isTest
    static void testZoneFactors() {
        assertQuote(9.50, 2, 'DOMESTIC', false, null);  // x1.0
        assertQuote(13.30, 2, 'EU', false, null);       // 9.50 * 1.4
        assertQuote(20.90, 2, 'WORLD', false, null);    // 9.50 * 2.2
    }

    @isTest
    static void testZoneCaseInsensitive() {
        assertQuote(9.50, 2, 'domestic', false, null);
        assertQuote(13.30, 2, 'eu', false, null);
        assertQuote(20.90, 2, 'world', false, null);
        assertQuote(9.50, 2, 'Domestic', false, null);
    }

    @isTest
    static void testInvalidZones() {
        assertThrows(2, null, false, null);
        assertThrows(2, 'MARS', false, null);
        assertThrows(2, '', false, null);
    }

