        assertQuote(20.90, 2, 'WORLD', null, null);
    }

    @isTest
    static void testExpressOverridesFreeShipping() {
        // Express DOMESTIC with orderValue >= 100 is NOT free
        assertQuote(14.25, 2, 'DOMESTIC', true, 250.00);
        // And free-shipping check must not swallow express pricing elsewhere
        assertQuote(31.35, 3, 'WORLD', true, 250.00);
    }

    // ---------- free domestic standard shipping ----------

    @isTest
