        // just below threshold
        assertQuote(9.50, 2, 'DOMESTIC', false, 99.99);
        // order value null
        assertQuote(9.50, 2, 'DOMESTIC', false, null);
        // non-domestic zone with high order value
        assertQuote(13.30, 2, 'EU', false, 500.00);
        assertQuote(20.90, 2, 'WORLD', false, 500.00);
    }

    // ---------- rounding ----------

    @isTest
    static void testRoundingHalfUp() {
        // 21 kg DOMESTIC express: 18.75 * 1.5 = 28.125 -> 28.13
        assertQuote(28.13, 21, 'DOMESTIC', true, null);
        // 1 kg WORLD express: 5.00 * 2.2 = 11.00 * 1.5 = 16.50
        assertQuote(16.50, 1, 'WORLD', true, null);
        // 4 kg EU express: 9.50 * 1.4 = 13.30 * 1.5 = 19.95
        assertQuote(19.95, 4, 'EU', true, null);
        // 22 kg WORLD express: 19.50 * 2.2 = 42.90 * 1.5 = 64.35
        assertQuote(64.35, 22, 'WORLD', true, null);
        // 2 kg EU: 9.50 * 1.4 = 13.30
        assertQuote(13.30, 2, 'EU', false, null);
    }
