/**
 * Service class for importing leads from trade-show spreadsheets.
 * Reports per-row errors, defaults LeadSource, deduplicates emails
 * within a single call, and uses partial-success DML.
 */
public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Track normalized email -> first index seen, for intra-call duplicate detection.
        Map<String, Integer> seenEmails = new Map<String, Integer>();

        // Leads to insert, with their original input index.
        List<Lead> toInsert = new List<Lead>();
        Map<Integer, Integer> indexByLeadPosition = new Map<Integer, Integer>(); // position in toInsert -> input index

        for (Integer i = 0; i < leads.size(); i++) {
            Lead l = leads[i];
            if (l == null) {
                result.errorsByIndex.put(i, 'Null lead in input');
                continue;
            }

            String email = l.Email;
            if (String.isNotBlank(email)) {
                String normalized = email.trim().toLowerCase();
                if (seenEmails.containsKey(normalized)) {
                    result.errorsByIndex.put(
                        i,
                        'Duplicate email in import: ' + normalized
                    );
                    continue;
                }
                seenEmails.put(normalized, i);
            }

            if (String.isBlank(l.LeadSource)) {
                l.LeadSource = 'Web';
            }

            indexByLeadPosition.put(toInsert.size(), i);
            toInsert.add(l);
        }

        if (toInsert.isEmpty()) {
            return result;
        }

        // Single DML statement with partial success.
        List<Database.SaveResult> saveResults = Database.insert(
            toInsert, false // allOrNone = false
        );

        for (Integer pos = 0; pos < saveResults.size(); pos++) {
            Database.SaveResult sr = saveResults[pos];
            Integer inputIndex = indexByLeadPosition.get(pos);
            if (sr.isSuccess()) {
                result.successCount++;
                result.insertedIds.add(sr.getId());
            } else {
                List<String> messages = new List<String>();
                for (Database.Error err : sr.getErrors()) {
                    messages.add(err.getMessage());
                }
                result.errorsByIndex.put(inputIndex, String.join(messages, '; '));
            }
        }

        return result;
    }
}
