public with sharing class ShipmentEventHandler {

    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Last event in the list wins for each order number.
        Map<String, FB_Shipment_Event__e> eventByOrderNumber = new Map<String, FB_Shipment_Event__e>();
        Set<String> orderNumbers = new Set<String>();
        for (FB_Shipment_Event__e evt : events) {
            if (evt == null || String.isBlank(evt.Order_Number__c)) {
                continue;
            }
            String orderNumber = evt.Order_Number__c.trim().toUpperCase();
            orderNumbers.add(orderNumber);
            eventByOrderNumber.put(orderNumber, evt);
        }

        if (orderNumbers.isEmpty()) {
            return;
        }

        List<FB_Sales_Order__c> orders = [
            SELECT Id, Order_Number__c, Status__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :orderNumbers
        ];

        List<FB_Sales_Order__c> toUpdate = new List<FB_Sales_Order__c>();
        for (FB_Sales_Order__c order : orders) {
            if (order.Status__c == 'Cancelled') {
                continue;
            }
            FB_Shipment_Event__e evt = eventByOrderNumber.get(order.Order_Number__c);
            toUpdate.add(new FB_Sales_Order__c(
                Id = order.Id,
                Status__c = 'Shipped',
                Tracking_Number__c = evt.Tracking_Number__c,
                Carrier__c = evt.Carrier__c,
                Shipped_Date__c = Date.today()
            ));
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
