public with sharing class ErpSyncFinalizer implements Finalizer {

    private final Set<Id> accountIds;
    private final Integer attempt;
    private static final Integer MAX_ATTEMPTS = 3;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext ctx) {
        FB_Job_Log__c log = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = this.attempt
        );

        Boolean success = ctx.getResult() == ParentJobResult.SUCCESS;
        if (success) {
            log.Status__c = 'Success';
        } else {
            log.Status__c = 'Failed';
            Exception cause = ctx.getException();
            String message = cause != null && cause.getMessage() != null
                ? cause.getMessage()
                : 'Unknown error';
            if (message.length() > 255) {
                message = message.substring(0, 255);
            }
            log.Error__c = message;
        }

        insert log;

        if (!success && this.attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(this.accountIds, this.attempt + 1));
        }
    }
}
