trigger OpportunityTrigger on Opportunity (after insert, after update, after delete, after undelete) {
    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isDelete) {
        for (Opportunity o : Trigger.old) {
            if (o.AccountId != null) {
                accountIds.add(o.AccountId);
            }
        }
    } else {
        for (Opportunity o : Trigger.new) {
            if (Trigger.isInsert || Trigger.isUndelete) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            } else {
                Opportunity oldOppo = Trigger.oldMap.get(o.Id);
                // Only recalculate when a field that affects the totals changed.
                // This also breaks the recursion with the legacy AccountTrigger
                // (which updates open opportunities with the account rating).
                if (oldOppo.Amount != o.Amount
                        || oldOppo.IsClosed != o.IsClosed
                        || oldOppo.AccountId != o.AccountId) {
                    if (o.AccountId != null) {
                        accountIds.add(o.AccountId);
                    }
                    if (oldOppo.AccountId != null) {
                        accountIds.add(oldOppo.AccountId);
                    }
                }
            }
        }
    }

    OpportunityPipelineHandler.recalculate(accountIds);
}
