/**
 * Schedulable job that purges old FB_Integration_Log__c records.
 *  - Non-ERROR logs are deleted after 30 days.
 *  - ERROR logs are kept until 180 days old.
 */
public with sharing class LogPurgeJob implements Schedulable {

    private static final Integer STANDARD_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final String CRON_EXPRESSION = '0 0 2 * * ?';
    private static final String JOB_NAME = 'Log purge (nightly)';

    /** No-argument constructor required by the scheduler. */
    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        purgeLogs();
    }

    /**
     * Deletes logs older than the applicable retention period.
     * Level__c is NULLable; NULL is treated as a non-ERROR level (30 days).
     */
    public static void purgeLogs() {
        Datetime now = Datetime.now();

        List<Fb_Integration_Log__c> toDelete = new List<Fb_Integration_Log__c>();

        // Non-ERROR (including blank) older than 30 days.
        toDelete.addAll([
            SELECT Id
            FROM Fb_Integration_Log__c
            WHERE CreatedDate < :now.addDays(-STANDARD_RETENTION_DAYS)
              AND (Level__c != 'ERROR' OR Level__c = null)
        ]);

        // ERROR logs older than 180 days.
        toDelete.addAll([
            SELECT Id
            FROM Fb_Integration_Log__c
            WHERE CreatedDate < :now.addDays(-ERROR_RETENTION_DAYS)
              AND Level__c = 'ERROR'
        ]);

        if (!toDelete.isEmpty()) {
            // Bulk-safe delete with allOrNone=false so one failure
            // does not roll back the whole purge.
            List<Database.DeleteResult> results =
                Database.delete(toDelete, false);
        }
    }

    /**
     * Schedules the nightly purge at 02:00 every day.
     * @return The job Id returned by System.schedule.
     */
    public static Id scheduleNightly() {
        LogPurgeJob job = new LogPurgeJob();
        return System.schedule(JOB_NAME, CRON_EXPRESSION, job);
    }
}
