@isTest
private class InvoicingServiceTest {

    /**
     * Hand-rolled fake of the billing gateway so that NO callouts ever happen
     * and so that we can assert call ordering (authenticate before createInvoice),
     * which plain ApexMocks stubbing cannot easily express.
     * It is injected via Application.Service.setMock.
     */
    private class GatewayMock implements IBillingGateway {
        Integer authenticateCallCount = 0;
        List<String> callOrder = new List<String>();
        List<Id> invoicedAccountIds = new List<Id>();
        List<Decimal> invoicedAmounts = new List<Decimal>();
        Map<Id, String> invoiceNumbersByAccountId = new Map<Id, String>();
        Set<Id> failingAccountIds = new Set<Id>();
        String failingMessage = 'Card declined';
        String authenticateExceptionMessage;

        public void authenticate() {
            callOrder.add('authenticate');
            authenticateCallCount++;
            if (authenticateExceptionMessage != null) {
                throw new BillingException(authenticateExceptionMessage);
            }
        }

        public String createInvoice(Id accountId, Decimal amount) {
            callOrder.add('createInvoice');
            invoicedAccountIds.add(accountId);
            invoicedAmounts.add(amount);
            if (failingAccountIds.contains(accountId)) {
                throw new BillingException(failingMessage);
            }
            return invoiceNumbersByAccountId.get(accountId);
        }

        Integer createInvoiceCallCount() {
            return invoicedAccountIds.size();
        }
    }

    private static Opportunity makeOpp(String stage, Decimal amount, Id accountId) {
        Opportunity opp = new Opportunity();
        opp.Id = fflib_IDGenerator.generate(Opportunity.SObjectType);
        opp.AccountId = accountId;
        opp.StageName = stage;
        opp.Amount = amount;
        return opp;
    }

    private static Set<Id> toIds(List<Opportunity> opps) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity opp : opps) {
            ids.add(opp.Id);
        }
        return ids;
    }

    @isTest
    static void testNullOrEmptyIdSetReturnsZero() {
        Assert.AreEqual(0, InvoicingService.invoiceWonOpportunities(null),
            'null id set should return 0');
        Assert.AreEqual(0, InvoicingService.invoiceWonOpportunities(new Set<Id>()),
            'empty id set should return 0');
    }

    @isTest
    static void testAuthenticateFailureThrowsInvoicingExceptionAndDoesNothing() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        GatewayMock gatewayMock = new GatewayMock();
        gatewayMock.authenticateExceptionMessage = 'invalid client credentials';
        Application.Service.setMock(IBillingGateway.class, gatewayMock);

        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Opportunity opp = makeOpp('Closed Won', 500, accountId);
        List<Opportunity> opps = new List<Opportunity>{ opp };

        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        mocks.startStubbing();
        mocks.when(selectorMock.selectById(toIds(opps))).thenReturn(opps);
        mocks.stopStubbing();
        Application.Selector.setMock(selectorMock);

        fflib_ISObjectUnitOfWork uowMock =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(uowMock);

        try {
            InvoicingService.invoiceWonOpportunities(toIds(opps));
            Assert.fail('Expected InvoicingService.InvoicingException');
        } catch (InvoicingService.InvoicingException e) {
            Assert.isTrue(e.getMessage().contains('invalid client credentials'),
                'Exception message should wrap gateway message. Got: ' + e.getMessage());
        }

        // nothing invoiced
        Assert.areEqual(0, gatewayMock.createInvoiceCallCount(),
            'No invoice should be created when authentication fails');

        // nothing registered, nothing committed
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never()))
            .registerDirty(fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never()))
            .commitWork();
