/**
 * Domain class for Opportunity, following the fflib Apex Enterprise Patterns.
 */
public inherited sharing class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    /**
     * Inner class the fflib framework uses to construct the domain class
     * from the trigger handler.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records == null
                ? new List<Opportunity>()
                : records.castTo(List<Opportunity>.class));
        }
    }

    public override void onBeforeInsert() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.CloseDate == null) {
                opp.CloseDate = Date.today().addDays(30);
            }
            if (opp.Type == null) {
                opp.Type = 'New Customer';
            }
        }
    }
}
