        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    public override List<Schema.FieldSet> getSObjectFieldSetList() {
        return new List<Schema.FieldSet>{
            Schema.SObjectType.Account.fieldSets.getCredit_Review()
        };
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        ContactsSelector contactsSelector = new ContactsSelector();
        String contactSubquery = contactsSelector.getQuery(
            'AccountId',
            new List<fflib_QueryFactory.Filter>{}
        );
        fflib_QueryFactory queryFactory = newQueryFactory()
            .setCondition('Id IN :accountIds')
            .addSubquery(contactSubquery);
        return Database.query(queryFactory.toSOQL());
    }
}
```

Notes:

- **User mode**: the third constructor argument (`enforceCRUD = true`) makes fflib build queries via `fflib_QueryFactory`, which appends `WITH USER_MODE` (in current fflib-apex-common versions, `Database.query` with security enforcement). This means a user lacking read access to any selected field (e.g., a field later added to `Credit_Review`) gets a query exception rather than silently omitted data — the platform enforces object, field and sharing access for the running user.
- **Field set**: overriding `getSObjectFieldSetList()` causes every query factory built by this selector to include all fields of the `Credit_Review` field set dynamically — admins can add fields without code changes.
- **Contacts subquery**: `ContactsSelector.getQuery()` builds a fully qualified subquery with that selector's field list; the outer query factory composes it as a child subquery so both queries execute in one SOQL statement.

