public with sharing class CaseSurveyJob implements Queueable {

    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseId AND IsClosed = true
        ];
        if (cases.isEmpty() || cases[0].ContactId == null) {
            return; // No contact -> no task, per requirements.
        }

        Case c = cases[0];
        insert new Task(
            WhatId      = c.Id,
            WhoId       = c.ContactId,
            Subject     = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status      = 'Not Started'
        );
        // Future vendor integration would be called from here, still
        // asynchronously and isolated per case.
    }
}
