import { LightningElement, wire, track } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    _debounceTimeoutId;
    _pendingRequestId = 0;
    _hasRendered = true;

    handleSearchChange(event) {
        const searchTerm = event.target.value.trim();

        this._cancelPendingSearch();

        if (searchTerm.length < MIN_SEARCH_LENGTH) {
            this.contacts = [];
            this.error = undefined;
            return;
        }

        this._debounceTimeoutId = setTimeout(() => {
            this._debounceTimeoutId = null;
            this._executeSearch(searchTerm);
        }, DEBOUNCE_MS);
    }

    _cancelPendingSearch() {
        if (this._debounceTimeoutId) {
            clearTimeout(this._debounceTimeoutId);
            this._debounceTimeoutId = null;
        }
        this._pendingRequestId++;
    }

    _executeSearch(searchTerm) {
        const requestId = this._pendingRequestId;

        searchContacts({ searchTerm })
            .then((result) => {
                if (!this._hasRendered || requestId !== this._pendingRequestId) {
                    return;
                }
                this.contacts = result;
                this.error = undefined;
            })
            .catch((error) => {
                if (!this._hasRendered || requestId !== this._pendingRequestId) {
                    return;
                }
                this.error = error.body && error.body.message
                    ? error.body.message
                    : 'An unexpected error occurred.';
                this.contacts = [];
            });
    }

    disconnectedCallback() {
        this._hasRendered = false;
        this._cancelPendingSearch();
    }
}
