import { LightningElement, api } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    @api title = 'Support Queue Monitor';

    waiting;
    longestWaitMinutes;
    error;
    loaded = false;

    #intervalId = null;
    #inFlight = false;
    #visibilityHandler = null;

    connectedCallback() {
        this.#visibilityHandler = () => {
            if (document.visibilityState === 'visible') {
                this.#restart();
            }
        };
        document.addEventListener('visibilitychange', this.#visibilityHandler);
        this.#start();
    }

    disconnectedCallback() {
        this.#stop();
        if (this.#visibilityHandler) {
            document.removeEventListener('visibilitychange', this.#visibilityHandler);
            this.#visibilityHandler = null;
        }
    }

    #start() {
        this.loadStats();
        this.#intervalId = setInterval(() => {
            if (document.visibilityState === 'hidden') {
                return; // skip refresh while tab is hidden
            }
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    #stop() {
        if (this.#intervalId !== null) {
            clearInterval(this.#intervalId);
            this.#intervalId = null;
        }
    }

    #restart() {
        this.#stop();
        this.#start();
    }

    loadStats() {
        if (this.#inFlight) {
            return; // skip; previous request still in flight
        }
        this.#inFlight = true;
        getQueueStats()
            .then((result) => {
                if (result) {
                    this.waiting = result.waiting;
                    this.longestWaitMinutes = result.longestWaitMinutes;
                    this.error = undefined;
                    this.loaded = true;
                }
            })
            .catch((error) => {
                this.error = this.#reduceError(error);
            })
            .finally(() => {
                this.#inFlight = false;
            });
    }

    #reduceError(error) {
        if (error && error.body && error.body.message) {
            return error.body.message;
        }
        return 'An unexpected error occurred.';
    }
}
