import { LightningElement, api, track } from 'lwc';

const NAV_KEYS = new Set([
    'ArrowDown',
    'ArrowUp',
    'Home',
    'End',
    'Enter',
    ' '
]);

export default class StatusListbox extends LightningElement {
    @api label;
    @api
    get options() {
        return this._options || [];
    }
    set options(value) {
        this._options = (value || []).map((opt, index) => ({
            ...opt,
            key: `${index}-${opt.value}`
        }));
        this._syncActiveWithSelection();
    }

    @api
    get value() {
        return this._value;
    }
    set value(newValue) {
        this._value = newValue;
        this._syncActiveWithSelection();
    }

    _options = [];
    _value;
    _activeIndex = 0;

    get activeOption() {
        return this._options[this._activeIndex] || null;
    }

    get activeDescendantId() {
        return this.activeOption ? this.activeOption.id : null;
    }

    get selectedValue() {
        return this._value == null ? '' : this._value;
    }

    _syncActiveWithSelection() {
        const options = this._options || [];
        if (options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const index = options.findIndex((opt) => opt.value === this._value);
        this._activeIndex = index >= 0 ? index : 0;
    }

    handleKeydown(event) {
        const key = event.key;
        if (!NAV_KEYS.has(key)) {
            return;
        }
        event.preventDefault();

        const options = this.options;
        if (options.length === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(this._activeIndex + 1, options.length - 1);
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectActive();
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const li = event.target.closest('li[role="option"]');
        if (!li) {
            return;
        }
        const index = this._options.findIndex(
            (opt, i) =>
                this._optionId(i) === li.id
        );
        if (index < 0) {
            return;
        }
        this._activeIndex = index;
        this._selectActive();
    }

    _selectActive() {
        const option = this.activeOption;
        if (!option) {
            return;
        }
        if (option.value === this._value) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value },
                bubbles: false,
                composed: false
            })
        );
    }

    // Unique option ids (unique within the page via the component's own id)
    _uid = `slb-${Math.random().toString(36).slice(2, 9)}`;

    _optionId(index) {
        return `${this._uid}-option-${index}`;
    }

    get computedOptions() {
        return this._options.map((opt, index) => ({
            ...opt,
            id: this._optionId(index),
            ariaSelected: opt.value === this._value ? 'true' : 'false'
        }));
    }
}
