import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading = '';
    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get heading() {
        return this._heading;
    }

    set heading(value) {
        this._heading = value ? value.toUpperCase() : '';
    }

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = Array.isArray(value) ? value : [];
        this.items = this._tasks.map((task) => ({
            id: task.id,
            label: task.label,
            done: task.done
        }));
    }

    connectedCallback() {
        if (this.items.length === 0) {
            this.items = this._tasks.map((task) => ({
                id: task.id,
                label: task.label,
                done: task.done
            }));
        }
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = this.newLabel.trim();
        if (!label) {
            return;
        }
        this.items = [
            ...this.items,
            { id: `new-${this.nextId++}`, label: label, done: false }
        ];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label: label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        const index = this.items.findIndex((task) => task.id === id);
        if (index === -1) {
            return;
        }
        this.items = this.items.map((task, i) =>
            i === index ? { ...task, done: !task.done } : task
        );
    }
