```apex
/**
 * Sets the current primary employer (NPSP Affiliation) for contacts.
 *
 * Relies on NPSP's standard Affiliation trigger logic: creating a new
 * Affiliation with npe5__Primary__c = true and Status = 'Current' causes
 * NPSP to end-date and demote any previous primary affiliation (setting it
 * to 'Former' / non-primary with EndDate = today) and to update the
 * contact's npsp__Primary_Affiliation__c lookup automatically.
 *
 * For contacts whose organization is already their primary affiliation,
 * nothing is done (no duplicate affiliation is created).
 *
 * Governor limits: at most 2 SOQL queries and 2 DML statements per call,
 * so up to 200 contacts can be handled in a single invocation.
 */
public with sharing class EmployerService {

    private static final String STATUS_CURRENT = 'Current';

    /**
     * Sets the given Organization Account as each contact's current, primary affiliation.
     *
     * @param employerByContactId Map of Contact Id -> Organization Account Id.
     *                            Null or empty maps are ignored.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Remove null values / self-referential junk defensively.
        Map<Id, Id> validEntries = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId != null && orgId != null) {
                validEntries.put(contactId, orgId);
            }
        }
        if (validEntries.isEmpty()) {
            return;
        }

        // 1 SOQL: find existing Current primary affiliations for these contacts.
        Map<Id, npe5__Affiliation__c> primaryAffiliationByContact = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c, npe5__Primary__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :validEntries.keySet()
              AND npe5__Primary__c = true
              AND npe5__Status__c = :STATUS_CURRENT
        ]) {
            primaryAffiliationByContact.put(aff.npe5__Contact__c, aff);
        }

        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();

        for (Id contactId : validEntries.keySet()) {
            Id orgId = validEntries.get(contactId);

            npe5__Affiliation__c existing = primaryAffiliationByContact.get(contactId);
            // Already the primary, current affiliation -> nothing to do.
            if (existing != null && existing.npe5__Organization__c == orgId) {
                continue;
            }

            toInsert.add(new npe5__Affiliation__c(
                npe5__Contact__c     = contactId,
                npe5__Organization__c = orgId,
                npe5__Status__c      = STATUS_CURRENT,
                npe5__Primary__c     = true,
                npe5__StartDate__c   = Date.today()
            ));
        }

        // 1 DML: insert all new affiliations in bulk. NPSP's trigger demotes the
        // previous primary affiliation (Former, non-primary, EndDate = today)
        // and updates Contact.npsp__Primary_Affiliation__c to the organization.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
```

