```apex
/**
 * GiftImportService
 *
 * Stages one-off web gifts as NPSP Data Import (BDI) records and processes
 * them synchronously through NPSP's own data import engine, so NPSP's
 * contact matching, household creation and donation processing rules apply.
 * Each staged npsp__DataImport__c record is retained in the org as the
 * audit trail of what was imported.
 *
 * Bulk-safe: a single synchronous transaction handles up to 200 gifts.
 */
public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Imports a list of web gifts through NPSP's Data Import engine.
     * Returns one ImportResult per gift, in input order. A row that NPSP
     * rejects does not stop the others; its result carries NPSP's failure
     * message.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one NPSP Data Import record per gift.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            staged.add(buildDataImport(gift));
        }

        List<Database.SaveResult> insertResults =
            Database.insert(staged, false); // partial success: bad rows shouldn't block others

        // Map each staged record (by position) to its Id; only successfully
        // inserted staging rows can be processed by NPSP.
        List<Id> processableIds = new List<Id>();
        Map<Integer, Id> stagedIdByIndex = new Map<Integer, Id>();
        List<String> insertErrors = new List<String>();
        for (Integer i = 0; i < insertResults.size(); i++) {
            if (insertResults[i].isSuccess()) {
                stagedIdByIndex.put(i, staged[i].Id);
                processableIds.add(staged[i].Id);
            } else {
                List<String> msgs = new List<String>();
                for (Database.Error err : insertResults[i].getErrors()) {
                    msgs.add(err.getStatusCode() + ': ' + err.getMessage());
                }
                insertErrors.add(String.join(msgs, '; '));
            }
        }

        // Process the staged rows synchronously through NPSP's BDI Apex API.
        // NPSP's data import applies the org's Data Import settings
        // (npsp__Data_Import_Settings__c), including contact matching rules
        // and "do not match existing donations" behavior.
        if (!processableIds.isEmpty()) {
            npsp.BDI_API.process(processableIds);
        }

        // Re-query the processed staging records to read NPSP's results.
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>(
            processableIds.isEmpty()
                ? new List<npsp__DataImport__c>()
                : [SELECT Id,
                          npsp__Status__c,
                          npsp__Contact1Imported__c,
                          npsp__DonationImported__c,
                          npsp__FailureInformation__c
                   FROM npsp__DataImport__c
                   WHERE Id IN :processableIds]
        );

        // Build one result per input gift, in input order.
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult result = new ImportResult();
            result.success = false;

            Id stagedId = stagedIdByIndex.get(i);
            if (stagedId == null) {
                // Staging insert itself failed.
                result.errorMessage = insertErrors[i];
                results.add(result);
                continue;
            }

            npsp__DataImport__c row = processed.get(stagedId);
            if (row == null) {
                result.errorMessage = 'NPSP Data Import record could not be read after processing.';
                results.add(result);
                continue;
            }

            result.contactId = row.npsp__Contact1Imported__c;
            result.opportunityId = row.npsp__DonationImported__c;

            // NPSP reports success via the Status field, e.g. 'Imported'.
            String status = row.npsp__Status__c;
            if (status != null && status.equalsIgnoreCase('Imported')) {
                result.success = true;
            } else {
                result.errorMessage = row.npsp__FailureInformation__c != null
                    ? row.npsp__FailureInformation__c
                    : 'NPSP Data Import status: ' + status;
            }
            results.add(result);
        }

        return results;
    }

    /**
     * Builds a staged NPSP Data Import record for one web gift.
     * The donation donor is Contact1 so NPSP applies its contact matching
     * (first name, last name, email) and household rules.
     */
    private static npsp__DataImport__c buildDataImport(WebGift gift) {
        npsp__DataImport__c row = new npsp__DataImport__c();
        row.npsp__Contact1_Firstname__c = gift.firstName;
        row.npsp__Contact1_Lastname__c = gift.lastName;
        row.npsp__Contact1_Personal_Email__c = gift.email;
        row.npsp__Donation_Amount__c = gift.amount;
        row.npsp__Donation_Date__c = gift.giftDate;
        row.npsp__Donation_Donor__c = 'Contact1';
        return row;
    }
}
```

Notes on the implementation:

- **NPSP's own engine**: rows are staged as `npsp__DataImport__c` and processed via `npsp.BDI_API.process(List<Id>)`, which runs BDI synchronously in the same transaction and honors the org's `npsp__Data_Import_Settings__c` (contact matching on first/last/email, no donation matching).
- **Audit trail**: the staged Data Import records are inserted and never deleted, so each remains in the org with NPSP's written-back status, imported Contact/Opportunity lookups, and failure information.
- **Row-level resilience**: staging uses `Database.insert(..., false)`, and BDI marks individual rows `Failed` rather than aborting the batch, so one bad gift doesn't block the rest; the results map each row's `npsp__FailureInformation__c` back to the caller.
- **Order and limits**: results are built by input index, and a single call handles 200 gifts within one transaction.

