/**
 * Manages NPSP partial soft credits for peer-to-peer fundraising.
 * Bulk-safe: handles up to 200 requests with at most 4 SOQL and 2 DML statements.
 */
public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Creates or updates partial soft credits for the given requests.
     * Validates the entire batch before performing any DML; throws
     * SoftCreditException and makes no changes if any request is invalid.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req == null) {
                throw new SoftCreditException('Null request in list.');
            }
            opportunityIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // SOQL 1 & 2: opportunities and contacts
        Map<Id, Opportunity> oppsById = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :opportunityIds]);

        Map<Id, Contact> contactsById = new Map<Id, Contact>(
            [SELECT Id FROM Contact WHERE Id IN :contactIds]);

        // Validate everything before any DML.
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppsById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + req.opportunityId);
            }
            if (contactsById.get(req.contactId) == null) {
                throw new SoftCreditException(
                    'Contact not found: ' + req.contactId);
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException(
                    'Amount must be a positive number for contact ' + req.contactId +
                    ' on opportunity ' + req.opportunityId + '.');
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Amount ' + req.amount + ' exceeds opportunity amount for contact ' +
                    req.contactId + ' on opportunity ' + req.opportunityId + '.');
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId +
                    ' is the primary contact on opportunity ' + req.opportunityId +
                    ' and cannot receive a partial soft credit.');
            }
        }

        // SOQL 3 & 4: existing contact roles and partial soft credits
        Map<String, OpportunityContactRole> ocrByKey = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
              AND ContactId IN :contactIds
        ]) {
            ocrByKey.put(ocr.OpportunityId + '|' + ocr.ContactId, ocr);
        }

        Map<String, npsp__Partial_Soft_Credit__c> pscByKey =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            pscByKey.put(psc.npsp__Opportunity__c + '|' + psc.npsp__Contact__c, psc);
        }

        // Determine contact names for npsp__Contact_Name__c
        Map<Id, String> contactNames = new Map<Id, String>();
        for (Contact c : [SELECT Id, Name FROM Contact WHERE Id IN :contactIds]) {
            contactNames.put(c.Id, c.Name);
        }

        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;

            // Ensure exactly one OCR with the requested role.
            OpportunityContactRole ocr = ocrByKey.get(key);
            if (ocr == null) {
                ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    IsPrimary = false);
            }
            ocr.Role = req.role;
            ocrsToUpsert.add(ocr);

            // Create or update the partial soft credit.
            npsp__Partial_Soft_Credit__c psc = pscByKey.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId);
            }
            psc.npsp__Amount__c = req.amount;
            psc.npsp__Role_Name__c = req.role;
            psc.npsp__Contact_Role_ID__c = ocr.Id; // null for new OCRs, set after upsert
            psc.npsp__Contact_Name__c = contactNames.get(req.contactId);
            pscsToUpsert.add(psc);
        }

        // DML 1: upsert contact roles
        upsert ocrsToUpsert;

        // Link newly created OCR Ids back to the soft credits.
        Map<String, Id> ocrIdByKey = new Map<String, Id>();
        for (OpportunityContactRole ocr : ocrsToUpsert) {
            ocrIdByKey.put(ocr.OpportunityId + '|' + ocr.ContactId, ocr.Id);
        }
        for (npsp__Partial_Soft_Credit__c psc : pscsToUpsert) {
            Id ocrId = ocrIdByKey.get(psc.npsp__Opportunity__c + '|' + psc.npsp__Contact__c);
            if (ocrId != null) {
                psc.npsp__Contact_Role_ID__c = ocrId;
            }
        }

        // DML 2: upsert partial soft credits
        upsert pscsToUpsert;
    }
}
```

Notes on the implementation:

- **Governor limits**: exactly 4 SOQL queries (opportunities, contact roles, partial soft credits, contact names) and 2 DML statements (`upsert` on OCRs, `upsert` on PSCs) regardless of the number of requests (≤200).
- **All-or-nothing validation**: every request is validated (contact not the NPSP primary contact, amount non-null, positive, ≤ opportunity amount, and both records exist) before any DML runs, so an invalid request leaves the org untouched. `upsert` is atomic per call anyway.
- **Exactly one OCR per contact/opp**: existing roles (e.g., NPSP's `Household Member`) are updated to the requested role rather than duplicated; new ones are created when absent.
- **Idempotency**: an existing partial soft credit for the same opp/contact pair is updated (amount and role) rather than duplicated, and `npsp__Contact_Role_ID__c` is refreshed to the (possibly new) OCR Id.
- **Security**: `with sharing` is used, and field-level security can be enforced via `WITH SECURITY_ENFORCED` additions if the org requires it.

