public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be at least 1.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('firstPaymentDate is required.');
        }
        if (opportunityId == null) {
            throw new PaymentPlanException('opportunityId is required.');
        }

        List<String> eFields = new List<String>{
            'Id', 'IsClosed', 'Amount',
            'npe01__OppPayment__r.npe01__Payment_Amount__c',
            'npe01__OppPayment__r.npe01__Paid__c',
            'npe01__OppPayment__r.npe01__Written_Off__c'
        };
        List<Opportunity> opps = Database.query(
            'SELECT ' + String.join(eFields, ',') + ' FROM Opportunity WHERE Id = :opportunityId'
        );
        if (opps.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }
        Opportunity opp = opps[0];

        if (opp.IsClosed) {
            throw new PaymentPlanException('Opportunity is closed; cannot schedule installments.');
        }

        Decimal outstanding = opp.Amount == null ? 0 : opp.Amount;
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c pmt : opp.npe01__OppPayment__r) {
            Boolean isHistory = (pmt.npe01__Paid__c == true) || (pmt.npe01__Written_Off__c == true);
            if (isHistory) {
                if (pmt.npe01__Payment_Amount__c != null) {
                    outstanding -= pmt.npe01__Payment_Amount__c;
                }
            } else {
                toDelete.add(pmt);
            }
        }
        outstanding = outstanding.setScale(2);

        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount must be greater than zero. Calculated: ' + outstanding
            );
        }

        Decimal base = outstanding.divide(numberOfPayments, 2, RoundingMode.DOWN);
        List<npe01__OppPayment__c> installments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            installments.add(
                new npe01__OppPayment__c(
                    npe01__Opportunity__c = opportunityId,
                    npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                    npe01__Payment_Amount__c = base
                )
            );
        }
        // Last payment absorbs rounding remainder.
        installments[numberOfPayments - 1].npe01__Payment_Amount__c =
            outstanding - (base * (numberOfPayments - 1));

        Savepoint sp = Database.setSavepoint();
        try {
            if (!toDelete.isEmpty()) {
                delete toDelete;
            }
            insert installments;
        } catch (DmlException e) {
            Database.rollback(sp);
            throw new PaymentPlanException(
                'Failed to schedule installments: ' + e.getDmlMessage(0), e
            );
        }

        return installments;
    }
}
