File: force-app/main/default/classes/AccountOwnershipService.cls

```apex
/**
 * Service for reassigning books of business between reps.
 *
 * Sets the new owner on the given Accounts and on all Contacts of those
 * Accounts. Account trigger actions (TAF) are bypassed for the duration of
 * the reassignment because they recalculate territories and are expensive.
 * Contact trigger actions run normally.
 *
 * The Account bypass is always cleared, even if DML fails, so that Account
 * automation behaves normally for the rest of the transaction.
 */
public inherited sharing class AccountOwnershipService {

    /**
     * Reassigns the given Accounts and their Contacts to a new owner.
     *
     * @param accountIds  Set of Account Ids to reassign (up to 200).
     * @param newOwnerId  Id of the new owner (User or Queue).
     * @throws DmlException if the update fails (all-or-none); propagates to caller.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        try {
            MetadataTriggerHandler.bypass(Account.SObjectType);

            // Query 1: Accounts to update.
            List<Account> accounts = [
                SELECT Id
                FROM Account
                WHERE Id IN :accountIds
            ];
            for (Account acc : accounts) {
                acc.OwnerId = newOwnerId;
            }

            // Query 2: Contacts of those Accounts to update.
            List<Contact> contacts = [
                SELECT Id
                FROM Contact
                WHERE AccountId IN :accountIds
            ];
            for (Contact con : contacts) {
                con.OwnerId = newOwnerId;
            }

            if (!accounts.isEmpty()) {
                // DML 1: Account triggers are bypassed via TAF.
                update accounts;
            }
            if (!contacts.isEmpty()) {
                // DML 2: Contact triggers run normally.
                update contacts;
            }
        } finally {
            // Restore normal Account automation for the rest of the
            // transaction, whether or not the DML succeeded.
            MetadataTriggerHandler.clearBypass(Account.SObjectType);
        }
    }
}
```

