```apex
/**
 * Trigger Action: prevents two Contacts of the same Account from sharing an
 * email address (case-insensitive). Contacts without an Account or without an
 * Email are not checked. On update, only records whose Email or AccountId
 * changed are validated, and a contact never conflicts with itself.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate(triggerNew, new Map<Id, SObject>());
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);
        validate(triggerNew, oldMap);
    }

    private void validate(List<SObject> records, Map<Id, SObject> oldMap) {
        List<Contact> candidates = new List<Contact>();
        Set<Id> processedIds = new Set<Id>();

        for (SObject so : records) {
            Contact c = (Contact) so;
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }
            Boolean changed;
            if (oldMap.isEmpty() == false && oldMap.containsKey(c.Id)) {
                Contact old = (Contact) oldMap.get(c.Id);
                changed = (c.Email != old.Email || c.AccountId != old.AccountId);
            } else {
                // before insert (no old record): always check
                changed = true;
            }
            if (changed) {
                candidates.add(c);
            }
            processedIds.add(c.Id);
        }

        if (candidates.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        for (Contact c : candidates) {
            accountIds.add(c.AccountId);
            emails.add(normalize(c.Email));
        }

        // Single SOQL query: existing contacts that could conflict.
        // Self is excluded via processedIds so a contact never conflicts with itself.
        Set<String> existingKeys = new Set<String>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
              AND (NOT Id IN :processedIds)
        ]) {
            if (emails.contains(normalize(existing.Email))) {
                existingKeys.add(key(existing.AccountId, existing.Email));
            }
        }

        // Validate in list order: the first record for a given account + email
        // is accepted, later ones are rejected.
        for (Contact c : candidates) {
            String k = key(c.AccountId, c.Email);
            if (existingKeys.contains(k)) {
                c.addError(ERROR_MESSAGE);
            } else {
                existingKeys.add(k);
            }
        }
    }

    private static String normalize(String email) {
        return email == null ? '' : email.trim().toLowerCase();
    }

    private static String key(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + normalize(email);
    }
}
