public inherited sharing class TA_Case_RollupOpenCount
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete,
    TriggerAction.AfterUndelete {

    /**
     * Keeps Account.FB_Open_Case_Count__c equal to the number of the account's
     * Cases with IsClosed = false, for inserts, updates (close / reopen / reparent),
     * deletes and undeletes. Cases without an Account are ignored.
     *
     * Uses at most one SOQL (aggregate) and one DML statement per trigger execution.
     */

    public void afterInsert(List<SObject> triggerNew) {
        rollup(collectAffected(triggerNew, null));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        rollup(collectAffected(triggerNew, null));
    }

    public void afterDelete(List<SObject> triggerOld) {
        rollup(collectAffected(triggerOld, null));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Case> oldMap = new Map<Id, Case>();
        for (SObject so : triggerOld) {
            oldMap.put(so.Id, (Case) so);
        }
        rollup(collectAffected(triggerNew, oldMap));
    }

    /**
     * Determines which accounts' open-case counts may have changed.
     * For insert/undelete/delete only open cases with an account matter.
     * For update only records whose IsClosed or AccountId changed matter,
     * considering both the old and the new side of the change.
     */
    private static Set<Id> collectAffected(List<SObject> records, Map<Id, Case> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : records) {
            Case c = (Case) so;
            if (oldMap == null) {
                if (c.AccountId != null && !c.IsClosed) {
                    accountIds.add(c.AccountId);
                }
            } else {
                Case o = oldMap.get(c.Id);
                Boolean relevantChange =
                    o.IsClosed != c.IsClosed || o.AccountId != c.AccountId;
                if (relevantChange) {
                    // Old side: was this case counted against its old account?
                    if (o.AccountId != null && !o.IsClosed) {
                        accountIds.add(o.AccountId);
                    }
                    // New side: is this case now counted against its new account?
                    if (c.AccountId != null && !c.IsClosed) {
                        accountIds.add(c.AccountId);
                    }
                }
            }
        }
        return accountIds;
    }

    /**
     * Recomputes the open-case count for every affected account and writes it
     * in a single DML statement. Accounts with no open cases get 0 (not blank).
     */
    private static void rollup(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCounts = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId accountId, COUNT(Id) cnt
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCounts.put((Id) ar.get('accountId'), (Integer) ar.get('cnt'));
        }

        List<Account> toUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            toUpdate.add(new Account(
                Id = accountId,
                FB_Open_Case_Count__c = openCounts.containsKey(accountId)
                    ? openCounts.get(accountId)
                    : 0
            ));
        }
        update toUpdate;
    }
}
```

