public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    // Tracks opportunities already audited in this transaction so that the
    // recursive update performed by TA_Opportunity_RoundAmount (which re-fires
    // every Opportunity action, including this one) does not create a second
    // "Amount changed" task for the same user-initiated change.
    private static Set<Id> auditedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasks = new List<Task>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];

            // Only audit genuine Amount changes on update (inserts never reach here).
            if (newOpp.Amount == oldOpp.Amount) {
                continue;
            }

            // Skip if this opportunity was already audited earlier in the
            // same transaction (e.g. the rounding re-update).
            if (auditedOpportunityIds.contains(newOpp.Id)) {
                continue;
            }

            auditedOpportunityIds.add(newOpp.Id);
            tasks.add(new Task(
                Subject = 'Amount changed',
                WhatId = newOpp.Id,
                Status = 'Completed'
            ));
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
