/**
 * Singleton that exposes parent Account data to Contact trigger actions.
 * The inner Service class is registered as the first before-insert action
 * (Order 1) so it reloads the map on every trigger execution, and all other
 * actions share this single query instead of querying Accounts themselves.
 */
public inherited sharing class TA_Contact_Queries {

    public Map<Id, Account> accountsById { get; private set; }

    private static TA_Contact_Queries instance;

    private TA_Contact_Queries() {
        this.accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action that loads the parent Accounts for the contacts in this
     * trigger execution. Registered first (Order 1) in before insert so both
     * dependent actions can consume the map without their own queries.
     */
    public inherited sharing class Service implements TriggerAction.BeforeInsert {

        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject so : triggerNew) {
                Contact c = (Contact) so;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            Map<Id, Account> fresh = accountIds.isEmpty()
                ? new Map<Id, Account>()
                : new Map<Id, Account>([
                    SELECT Id, BillingStreet, BillingCity, BillingPostalCode,
                           BillingCountry, AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ]);

            // Reload on every trigger execution: later DML in the same
            // transaction may involve other accounts.
            TA_Contact_Queries.getInstance().accountsById = fresh;
        }
    }
}
