/**
 * Before insert: when a new Contact has an Account and all four mailing
 * address fields are blank, copy the Account's billing address into them.
 */
public inherited sharing class TA_Contact_InheritMailingAddress
    implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById =
            TA_Contact_Queries.getInstance().accountsById;

        for (SObject so : triggerNew) {
            Contact c = (Contact) so;
            if (c.AccountId == null) {
                continue;
            }

            if (String.isNotBlank(c.MailingStreet)
                || String.isNotBlank(c.MailingCity)
                || String.isNotBlank(c.MailingPostalCode)
                || String.isNotBlank(c.MailingCountry)) {
                continue;
            }

            Account acct = accountsById.get(c.AccountId);
            if (acct == null) {
                continue;
            }

            c.MailingStreet = acct.BillingStreet;
            c.MailingCity = acct.BillingCity;
            c.MailingPostalCode = acct.BillingPostalCode;
            c.MailingCountry = acct.BillingCountry;
        }
    }
}
